/* Array Decay Definition */
void func(int arr[]) {}     // Equivalent to:
void func(int* arr) {}

/* Multidimensional Array Decay */
// Outer dimension decays, inner dimensions must remain.
void process(int matrix[][5]) {} // Equivalent to:
void process(int (*matrix)[5]) {}

/* sizeof() Behavior (Crucial Difference) */
int global_arr[10]; // sizeof(global_arr) == 40 (10 * sizeof(int))

void check_size(int param_arr[]) {
    // param_arr has decayed to a pointer.
    // sizeof(param_arr) == sizeof(int*) (e.g., 8 bytes on 64-bit system)
}
